import { execa } from 'execa';
import { CliError, CliErrorCode } from '@wix/cli-error';

const DEBUGGER_FLAG = /^--(?:inspect|debug-port)/;
const CANCEL_SIGNALS = new Set(['SIGINT', 'SIGTERM']);

// The project config is loaded once per process, so each step runs in its own
// process to pick up what the previous step wrote.
//
// process.argv[1] is the CLI's entry script. Every way the CLI is installed
// (npx, yarn, global bins, Windows .cmd shims) ends up running
// `node <path>/bin/wix.cjs`, which loads the CLI in the same process, so
// argv[1] is always that file. execArgv carries Node flags such as Yarn PnP's
// loader; debugger flags are dropped so the child doesn't clash on the port or
// wait for a debugger to attach.
export async function runWixCommand(...args: string[]) {
  const [, cliEntryPath] = process.argv;
  if (cliEntryPath === undefined) {
    throw new CliError({
      code: CliErrorCode.UnknownFailure({
        error: new Error('process.argv has no CLI entry script'),
      }),
      cause: null,
    });
  }

  const command = ['wix', ...args].join(' ');
  const nodeFlags = process.execArgv.filter(
    (flag) => !DEBUGGER_FLAG.test(flag)
  );

  // Ctrl+C reaches the child too. Listening keeps this process alive until the
  // child exits, so the step is reported as canceled rather than failed.
  const interrupt = { isReceived: false };
  const onInterrupt = () => {
    interrupt.isReceived = true;
  };
  process.on('SIGINT', onInterrupt);
  try {
    const { failed, exitCode, signal } = await execa(
      process.execPath,
      [...nodeFlags, cliEntryPath, ...args],
      { stdio: 'inherit', reject: false }
    );

    if (
      interrupt.isReceived ||
      (signal !== undefined && CANCEL_SIGNALS.has(signal))
    ) {
      throw new CliError({
        code: CliErrorCode.FinalizeMigrationStepCanceled({ command }),
        cause: null,
        info: { exitCode, signal },
      });
    }

    if (failed) {
      throw new CliError({
        code: CliErrorCode.FinalizeMigrationStepFailed({ command }),
        cause: null,
        info: { exitCode, signal },
      });
    }
  } finally {
    process.off('SIGINT', onInterrupt);
  }
}
